local CiderPress = {}
local PRODUCTS = {
    farm_cider = { name = "Kmečki jabolčnik", appleCost = 3, time = 2, cost = 15, alcoholContent = 4, happiness = 2, description = "Kmečki jabolčnik za kmete." },
    spiced_cider = { name = "Začinjen jabolčnik", appleCost = 4, spiceCost = 1, time = 4, cost = 45, alcoholContent = 7, happiness = 3, prestige = 1, description = "Začinjen jabolčnik za zimske večere." },
    perry = { name = "Hruškovec", pearCost = 4, time = 4, cost = 50, alcoholContent = 7, happiness = 3, prestige = 2, description = "Hruškovec podoben jabolčniku." },
    oak_aged_cider = { name = "Hrastovo staran jabolčnik", appleCost = 5, oakCost = 1, time = 7, cost = 130, alcoholContent = 10, happiness = 5, prestige = 5, description = "Jabolčnik staran v hrastovem sodu." },
    silver_cask_cider = { name = "Srebrno sodni jabolčnik", appleCost = 6, silverCost = 1, oakCost = 1, time = 10, cost = 320, alcoholContent = 13, happiness = 8, prestige = 11, description = "Jabolčnik staran v srebrnem sodu." },
    royal_grand_cider = { name = "Kraljevski veliki jabolčnik", appleCost = 10, pearCost = 5, goldCost = 1, silverCost = 1, jewelCost = 1, oakCost = 2, spiceCost = 2, time = 16, cost = 1300, alcoholContent = 18, happiness = 16, prestige = 35, description = "Veliki kraljevski jabolčnik z zlatom in dragulji za kronanje." },
}
local BUILDINGS = {
    workshop = { name = "Jabolčniška delavnica", cost = { gold = 280, wood = 150 }, upkeep = 7, qualityBonus = 5 },
    press_house = { name = "Tisčnica", cost = { gold = 900, wood = 280, stone = 350, apple = 10 }, upkeep = 22, qualityBonus = 18 },
    aging_cellar = { name = "Starilni sklep", cost = { gold = 2200, wood = 400, stone = 700, silver = 30, oak = 8 }, upkeep = 55, qualityBonus = 30 },
    royal_cider_atelier = { name = "Kraljevski atelje jabolčnika", cost = { gold = 9000, wood = 600, stone = 1000, gold = 60, jewel = 20 }, upkeep = 180, qualityBonus = 55, prestigeBonus = 40 },
}
CiderPress.appleStock = 22; CiderPress.pearStock = 14; CiderPress.spiceStock = 10; CiderPress.oakStock = 12; CiderPress.silverStock = 8; CiderPress.goldStock = 6; CiderPress.jewelStock = 6
CiderPress.productStock = {}; CiderPress.buildings = {}; CiderPress.maker = nil; CiderPress.activeMaking = {}; CiderPress.totalProducts = 0; CiderPress.dayTimer = 0
function CiderPress.init() CiderPress.appleStock=22; CiderPress.pearStock=14; CiderPress.spiceStock=10; CiderPress.oakStock=12; CiderPress.silverStock=8; CiderPress.goldStock=6; CiderPress.jewelStock=6; CiderPress.productStock={}; CiderPress.buildings={}; CiderPress.maker=nil; CiderPress.activeMaking={}; CiderPress.totalProducts=0; CiderPress.dayTimer=0; print("[CiderPress] Royal Cider Press System initialized (6 products, 4 buildings)") end
function CiderPress.hireMaker(n,s) s=s or math.random(50,90); local c=500+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; CiderPress.maker={name=n or ("Jabolčničar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Jabolčničar najet: %s (spretnost: %d)",CiderPress.maker.name,s),"success") end; return true end
function CiderPress.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function CiderPress.build(id) local ok,e=CiderPress.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(CiderPress.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function CiderPress.getQualityBonus() local b=0; for _,bd in ipairs(CiderPress.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function CiderPress.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.appleCost and CiderPress.appleStock<(d.appleCost or 0) then return false,"Premalo jabolk" end; if d.pearCost and CiderPress.pearStock<(d.pearCost or 0) then return false,"Premalo hrušk" end; if d.spiceCost and CiderPress.spiceStock<(d.spiceCost or 0) then return false,"Premalo začimb" end; if d.oakCost and CiderPress.oakStock<(d.oakCost or 0) then return false,"Premalo hrasta" end; if d.silverCost and CiderPress.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and CiderPress.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and CiderPress.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if #CiderPress.buildings==0 then return false,"Potrebna delavnica" end; if not CiderPress.maker then return false,"Potreben jabolčničar" end; return true end
function CiderPress.make(pt,qty) qty=qty or 5; local ok,e=CiderPress.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.appleCost then CiderPress.appleStock=CiderPress.appleStock-d.appleCost*qty end; if d.pearCost then CiderPress.pearStock=CiderPress.pearStock-d.pearCost*qty end; if d.spiceCost then CiderPress.spiceStock=CiderPress.spiceStock-d.spiceCost*qty end; if d.oakCost then CiderPress.oakStock=CiderPress.oakStock-d.oakCost*qty end; if d.silverCost then CiderPress.silverStock=CiderPress.silverStock-d.silverCost*qty end; if d.goldCost then CiderPress.goldStock=CiderPress.goldStock-d.goldCost*qty end; if d.jewelCost then CiderPress.jewelStock=CiderPress.jewelStock-d.jewelCost*qty end; local t=d.time; if CiderPress.maker then t=math.max(1,t-math.floor(CiderPress.maker.skill/12)) end; table.insert(CiderPress.activeMaking,{id="cider_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,alcoholContent=d.alcoholContent or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function CiderPress.completeMaking(m) local q=1.0+(CiderPress.getQualityBonus()/100); if CiderPress.maker then q=q+(CiderPress.maker.skill/180) end; q=math.min(2.0,q); CiderPress.productStock[m.productType]=(CiderPress.productStock[m.productType] or 0)+m.quantity; CiderPress.totalProducts=CiderPress.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if CiderPress.maker then CiderPress.maker.itemsMade=CiderPress.maker.itemsMade+m.quantity; if math.random()<0.20 then CiderPress.maker.skill=math.min(100,CiderPress.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Jabolčnik izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"cider.completed",{productName=m.productName,alcoholContent=m.alcoholContent,happiness=m.happiness}) end end
function CiderPress.update(dt) if not _G.state then return end; CiderPress.dayTimer=CiderPress.dayTimer+dt; if CiderPress.dayTimer>=30 then CiderPress.dayTimer=0; for i=#CiderPress.activeMaking,1,-1 do local m=CiderPress.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then CiderPress.completeMaking(m); table.remove(CiderPress.activeMaking,i) end end; local tu=0; for _,bd in ipairs(CiderPress.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if CiderPress.maker then tu=tu+14 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function CiderPress.getStats() return {appleStock=CiderPress.appleStock,pearStock=CiderPress.pearStock,spiceStock=CiderPress.spiceStock,oakStock=CiderPress.oakStock,silverStock=CiderPress.silverStock,goldStock=CiderPress.goldStock,jewelStock=CiderPress.jewelStock,productStock=CiderPress.productStock,numBuildings=#CiderPress.buildings,hasMaker=CiderPress.maker~=nil,makerName=CiderPress.maker and CiderPress.maker.name or "—",makerSkill=CiderPress.maker and CiderPress.maker.skill or 0,activeMaking=#CiderPress.activeMaking,totalProducts=CiderPress.totalProducts} end
return CiderPress
